From db3d4bc0d58c081b9494f15d53a0c3bd5797518f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:29:15 +0100
Subject: [PATCH] shell: open the Activities switcher on the active screen

Meta+Q opened the Activities switcher on the screen where the pointer last
touched plasmashell, as QCursor::pos() is stale on Wayland. Ask KWin for
the active output instead, like the widget explorer already does.

BUG: 500197
---
 shell/shellcorona.cpp | 33 ++++++++++++++++++++-------------
 shell/shellcorona.h   |  1 +
 2 files changed, 21 insertions(+), 13 deletions(-)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..c640ae3d30 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -1755,42 +1755,49 @@ void ShellCorona::executeSetupPlasmoidScript(Plasma::Containment *containment, P
 #endif
 }

-void ShellCorona::toggleWidgetExplorer()
+DesktopView *ShellCorona::desktopForActiveOutput() const
 {
-    auto viewIt = m_desktopViewForScreen.cbegin();
     auto message = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/KWin"_s, u"org.kde.KWin"_s, u"activeOutputName"_s);
     QDBusReply<QString> reply = QDBusConnection::sessionBus().call(message);
     if (reply.isValid()) {
         const QString activeOutputName = reply.value();
-        viewIt = std::find_if(m_desktopViewForScreen.cbegin(), m_desktopViewForScreen.cend(), [&activeOutputName](DesktopView *view) {
-            return view->screen()->name() == activeOutputName;
-        });
+        for (DesktopView *view : std::as_const(m_desktopViewForScreen)) {
+            if (view->screen()->name() == activeOutputName) {
+                return view;
+            }
+        }
     }
+    return nullptr;
+}

-    if (viewIt == m_desktopViewForScreen.cend()) [[unlikely]] {
+void ShellCorona::toggleWidgetExplorer()
+{
+    DesktopView *view = desktopForActiveOutput();
+    if (!view) [[unlikely]] {
         Q_ASSERT_X(false, Q_FUNC_INFO, qUtf8Printable(std::invoke([this]() {
                        QString message;
                        QDebug(&message) << "m_desktopViewForScreen:" << m_desktopViewForScreen << "cursorPos:" << QCursor::pos();
                        return message;
                    })));
-        viewIt = m_desktopViewForScreen.cbegin();
+        view = *m_desktopViewForScreen.cbegin();
     }

     setEditMode(true);
     // The view QML has to provide something to display the widget explorer
-    QMetaObject::invokeMethod((*viewIt)->rootObject(), "toggleWidgetExplorer", Q_ARG(QVariant, QVariant::fromValue(sender())));
+    QMetaObject::invokeMethod(view->rootObject(), "toggleWidgetExplorer", Q_ARG(QVariant, QVariant::fromValue(sender())));
 }

 void ShellCorona::toggleActivityManager()
 {
-    const QPoint cursorPos = QCursor::pos();
-    for (DesktopView *view : std::as_const(m_desktopViewForScreen)) {
-        if (view->screen()->geometry().contains(cursorPos)) {
-            // The view QML has to provide something to display the activity explorer
-            view->rootObject()->metaObject()->invokeMethod(view->rootObject(), "toggleActivityManager", Qt::QueuedConnection);
+    DesktopView *view = desktopForActiveOutput();
+    if (!view) {
+        if (m_desktopViewForScreen.isEmpty()) {
             return;
         }
+        view = *m_desktopViewForScreen.cbegin();
     }
+    // The view QML has to provide something to display the activity explorer
+    view->rootObject()->metaObject()->invokeMethod(view->rootObject(), "toggleActivityManager", Qt::QueuedConnection);
 }

 void ShellCorona::syncAppConfig()
diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..081ad7ce69 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -284,6 +284,7 @@ private:
     void destroyDesktopsAndPanels();
     void updateStruts();
     DesktopView *desktopForScreen(QScreen *screen) const;
+    DesktopView *desktopForActiveOutput() const;
     void setupWaylandIntegration();
     void executeSetupPlasmoidScript(Plasma::Containment *containment, Plasma::Applet *applet);
     void checkAllDesktopsUiReady();
